import {escapeHTML as esc,num,pct} from './model.js';
import {lineChart} from './charts.js';
import {evaluate,historySeries,price,anchorEligible} from './domestic-model.js';
const money=x=>x===null||x===undefined||!Number.isFinite(x)?'미산정':Math.round(x).toLocaleString('ko-KR')+'원';
const seg=(key,items,selected)=>`<div class="segmented compact" role="group" aria-label="${esc(key)}">${items.map(([v,l])=>`<button data-action="${key}" data-value="${v}" aria-pressed="${v===selected}" class="${v===selected?'active':''}">${l}</button>`).join('')}</div>`;
const select=(key,label,items,value)=>`<label class="control" for="${key}">${label}<select id="${key}" aria-label="${esc(label)}" data-select="${key}">${items.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}</select></label>`;
const link=(url,text)=>`<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(text)} ↗</a>`;
const download=(url,label)=>`<a class="button" href="${url}" download>${label} ↓</a>`;
const pill=(text,tone='neutral')=>`<span class="buy-pill ${tone}">${esc(text)}</span>`;
const kind=m=>!m?'비교 지표 미확보':({'estimate':'간접추정','spec':'사양 지표','measured-single-game':'단일 게임 실측','same-chip-proxy':'동일칩 대용','measured-aggregate':'실측 제출 집계','measured-suite':'다종 게임 실측'}[m.kind]??m.kind);
function valueText(p,e){
 if(!e.metric||!e.current)return '가격 대비 지표 보류';
 if(p.category==='RAM'||(p.category==='SSD'&&e.metric.unit==='GB'))return money(e.current/e.metric.value)+'/GB';
 return `${num(e.metric.value,0)} ${e.metric.unit} · ${money(e.current/e.metric.value)}/${e.metric.unit}`;
}
function benchSection(D,all){
 const cpu=all.filter(p=>p.category==='CPU'),g=D.benchmarks.gpu;
 return `<section class="panel section-block"><div class="panel-head"><div><div class="eyebrow">MEASURED EVIDENCE</div><h2>CPU·GPU 실측 근거</h2><p class="panel-subtitle">PC 제출 집계와 통제된 게임 테스트를 구분 · 같은 칩의 여러 보드를 독립 성능 표본으로 세지 않음</p></div>${download('./data/downloads/domestic_benchmarks.csv','벤치마크 CSV')}</div><div class="panel-inner">
 <div class="benchmark-grid"><div><h3>CPU · PassMark 공식 집계</h3><p class="small-copy">2026-10-23 갱신. 서로 다른 PC의 제출 결과 평균. 표본은 제출 건수이며 독립 사용자 수는 미확인입니다. 게임 FPS를 뜻하지 않습니다.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>CPU</th><th>CPU Mark</th><th>단일 스레드</th><th>제출 n</th></tr></thead><tbody>${cpu.map(p=>`<tr><td>${link(p.performance.cpuMulti.sourceUrl,p.chip)}</td><td>${num(p.performance.cpuMulti.value,0)}</td><td>${num(p.performance.cpuSingle.value,0)}</td><td>${num(p.performance.cpuMulti.samples,0)}</td></tr>`).join('')}</tbody></table></div></div>
 <div><h3>GPU · TechPowerUp 공통 리뷰</h3><p class="small-copy">2025-06-21 발행 · 1440p 네이티브 · RT off · 23종 상대성능 · Pulse OC=100. 9800X3D/DDR5-6200, 카드별 드라이버 상이. 업스케일·프레임 생성 없음. 최신 패치 미반영.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>리뷰 GPU</th><th>상대성능</th><th>국내 견적</th></tr></thead><tbody>${g.bundle_1440p.cards.map(r=>{const available=all.some(p=>p.benchmarkCard===r.chip);return `<tr><td>${esc(r.chip)}</td><td>${r.relative_index_1440p_vs_pulse100}</td><td>${available?'확보':'미확보 · 추천 제외'}</td></tr>`}).join('')}</tbody></table></div></div></div>
 <p class="small-copy">23개는 게임 수입니다. 반복 실행 횟수·측정 오차·1% low는 미확보입니다. The Last of Us 충돌 항목을 뺀 상대성능을 기본 지표로 씁니다. 24슬롯 평균 FPS는 별도 지표이며 섞지 않습니다. 기존 Crimson Desert 45/116FPS도 별도 선택 항목으로 유지합니다.</p></div></section>`;
}
export function renderDomestic(main,D,state){
 const opts={basis:state.domBasis,quote:state.domQuote,cpu:state.domCpu,platform:state.domPlatform,gpu:state.domGpu,gpuScope:state.domGpuScope,vram:state.domVram,ssd:state.domSsd};
 const all=[...D.products,...D.marketReferences],eligible=all.filter(p=>anchorEligible(p,all)).length;
 let shown=all.filter(p=>(state.domCohort==='all'||p.cohort===state.domCohort)&&(state.domCategory==='all'||p.category===state.domCategory));
 if(!shown.some(p=>p.id===state.domProduct))state.domProduct=shown[0].id;
 const p=shown.find(p=>p.id===state.domProduct),e=evaluate(p,all,opts),q=p.quote,a=p.marketAudit;
 const selected=(state.domFrequency==='monthly'?p.history?.monthly_comparison_24m:p.history?.weekly_3m)??[];
 const pcN=selected.filter(r=>r.desktop_price!==null).length,mobN=selected.filter(r=>r.mobile_price!==null).length,conflicts=p.history?.monthly_comparison_24m.filter(r=>r.status!=='matched')??[];
 const others=all.filter(x=>x.category===p.category).map(x=>({p:x,e:evaluate(x,all,opts)}));
 const statLabel=state.domQuote==='median3'?'3몰 중앙값':'요약 최저 상품 견적',basisLabel=state.domBasis==='delivered'?'배송 포함':'상품가';
 const minimum=price(p,state.domBasis),median=price(p,state.domBasis,'median3');
 main.innerHTML=`<div class="page-head"><div><div class="eyebrow">DOMESTIC BUYING DESK / ${D.asOf.replaceAll('-','.')} KST</div><h1>지금의 가격, 살 만한 가치</h1><p class="subtitle">기존 8개 SKU + 비교 견적 13개. 가격의 두께와 성능 근거를 함께 확인하세요.</p></div>${download('./data/downloads/domestic_expanded.csv','전체 21개 견적 CSV')}</div>
 <div class="domestic-intro"><div><span class="live-label"><span class="status-dot"></span>저장된 가격 스냅샷 · 실시간 갱신 아님</span><strong>최저가 하나보다, 여러 견적과 공통 실측</strong><p>기본 가격은 배송비가 확인된 일반몰 상위 3곳의 중앙값입니다. 표시 판매처는 재고·판매량 확인을 뜻하지 않습니다.</p></div><button class="link-button" data-scroll="domestic-methods">산정 근거 보기 ↓</button></div>
 ${all.some(x=>evaluate(x,all,opts).stale)?'<div class="note section-block"><strong>가격 재조회 필요</strong><span>7일 초과·미래 시각 이상 견적의 구매 판단과 비교 지수를 보류했습니다.</span></div>':''}
 <div class="domestic-stats"><div><b>8 + 13</b><span>기존 SKU + 별도 비교 견적</span></div><div><b>${eligible} / ${all.length}</b><span>가격 앵커 조건 충족</span></div><div><b>4개 CPU</b><span>제품별 제출 n=5,987~9,982</span></div><div><b>23종</b><span>GPU 공통 게임 · 2025년 테스트</span></div></div>
 <div class="controls domestic-controls"><div class="control-group">${seg('domCohort',[['original','기존 8개'],['reference','비교 견적 13개'],['all','전체 21개']],state.domCohort)}${seg('domCategory',[['all','전체 부품'],['CPU','CPU'],['RAM','RAM'],['SSD','SSD'],['GPU','GPU']],state.domCategory)}</div><div class="control-group">${select('domBasis','배송 기준',[['delivered','배송 포함'],['product','상품가']],state.domBasis)}${select('domQuote','견적 기준',[['median3','상위 3몰 중앙값'],['lowest','요약 최저 상품 견적']],state.domQuote)}</div></div>
 <div class="domestic-grid">${shown.map(x=>{const v=evaluate(x,all,opts);return `<button class="product-card ${x.id===p.id?'selected':''}" data-action="domProduct" data-value="${x.id}" aria-pressed="${x.id===p.id}" aria-label="${esc(x.shortName)} 상세 보기"><div class="product-top"><span class="component-tag">${x.category} / ${x.cohort==='original'?'ORIGINAL':'REFERENCE'}</span>${pill(v.recommendation,v.tone)}</div><h2>${esc(x.shortName)}</h2><p class="product-spec">${esc(x.spec)}</p><div class="product-price">${money(v.current)}</div><div class="product-value">${esc(valueText(x,v))} · ${statLabel}</div><div class="product-bottom"><span>표시 ${x.quote.displayedSellerCount}곳 · 배송 확인 ${x.marketAudit.distinctDisplayedStoresWithShipping}몰</span><span>${v.index===null?'비교 지수 보류':`비교 지수 ${num(v.index,0)} / 100`}</span></div></button>`}).join('')}</div>
 <div class="section-row section-block domestic-detail-title"><div><div class="eyebrow">SELECTED PRODUCT / ${e.evidence}</div><h2>${esc(p.shortName)} · 구매 판단</h2></div>${link(q.sourceUrl,'현재 원문 확인')}</div>
 <div class="domestic-detail"><section class="panel"><div class="panel-inner"><div class="section-row"><h2>가격 대비 지표</h2>${pill(kind(e.metric))}</div>
 ${p.category==='CPU'?`<div class="domestic-option">${select('domCpu','CPU 성능 기준',[['multi','실측 제출 집계 · 멀티'],['single','실측 제출 집계 · 단일 스레드'],['bridge','이전 게임 간접추정']],state.domCpu)}${select('domPlatform','CPU 비교 범위',[['all','두 플랫폼 · 단품 비용'],['same','같은 소켓만']],state.domPlatform)}</div>`:''}
 ${p.category==='GPU'?`<div class="domestic-option">${select('domGpu','GPU 성능 기준',[['suite','23종 게임 · 1440p 상대성능'],['single','Crimson Desert · 단일 게임']],state.domGpu)}${select('domGpuScope','GPU 비교 범위',[['tier','같은 성능급'],['all','확보 GPU 전체']],state.domGpuScope)}${select('domVram','GPU 메모리 조건',[['any','8·16GB 함께 · 차이 확인'],['16','16GB 이상만']],state.domVram)}</div>`:''}
 ${p.category==='SSD'?`<div class="domestic-option">${select('domSsd','SSD 비교 기준',[['capacity','같은 1TB · TLC/DRAM 용량'],['read','공식 최대 순차 읽기 · 확보 2종']],state.domSsd)}</div>`:''}
 <div class="value-emphasis">${e.index===null?'—':num(e.index,0)}<span>${e.index===null?'비교 지수 미산정':'/ 100 · 선택 범위의 유효 지표/가격 최고 = 100'}</span></div><p class="value-description">${esc(valueText(p,e))}</p>
 <p class="small-copy">${e.metric?esc(e.metric.label):'선택한 공통 지표 미확보'}<br>유효 비교 ${e.peerN} SKU / ${e.chipN}개 비교 모델군 · ${basisLabel} · ${statLabel}${e.metric?.samples?`<br>대상 CPU 제출 n=${num(e.metric.samples,0)} · 독립 사용자 수 미확인`:''}</p>
 <div class="recommendation ${e.tone}">${pill(e.recommendation,e.tone)} ${pill(e.evidence)}<p>${esc(e.reason)}</p></div>
 <div class="compatibility"><strong>호환성 체크</strong><p>${esc(p.compatibility)}</p></div>
 ${e.metric?.note?`<p class="small-copy">${esc(e.metric.note)}</p>`:''}
 ${p.category==='GPU'?'<p class="small-copy">같은 성능급: 4060 대안은 5060·5060 Ti 16GB·9060 XT 16GB, 5070 Ti는 같은 칩 보드끼리 비교합니다. 성능급은 화면 분류 가정입니다. VRAM 8/16GB 차이·RT·전력·소음은 종합 점수에 반영하지 않았습니다.</p>':''}
 ${p.category==='RAM'?'<p class="small-copy">같은 DDR 세대·16GB 단품끼리만 비교합니다. 용량 지수는 실측 성능 지수가 아니며, CL·랭크·호환성 차이를 통제하지 못했습니다.</p>':''}
 ${p.category==='SSD'?'<p class="small-copy">용량 비교는 부팅·게임·지속 쓰기 성능 순위가 아닙니다. 990 PRO/P41만 제조사 최대 읽기 7,450/7,000MB/s를 확보했고, 새 2종에 임의 점수를 채우지 않았습니다.</p>':''}
 </div></section><section class="panel"><div class="panel-inner"><div class="section-row"><h2>가격 기준과 적정가 근거</h2><span class="pill">예측·확률 아님</span></div>
 <div class="fair-box"><span class="fair-label">01 / 현재 견적의 폭</span><strong>${money(median)} <small>3몰 중앙값</small></strong><p>요약 최저 상품의 ${basisLabel} ${money(minimum)}. 상품가·배송 포함을 각각 정렬해 일반몰 상위 3곳의 중앙값을 산출합니다. 카드·회원·현금 전용 가격과 배송비 미확인 행은 제외합니다.</p><div class="fair-formula">배송 포함 3몰 범위 ${money(a.top3DeliveredLow)} ~ ${money(a.top3DeliveredHigh)}<br>${a.top3Stores.map(esc).join(' · ')}${state.domBasis==='product'?'<br>상품가 기준 몰: '+a.top3ProductStores.map(esc).join(' · '):''}<br>배송 확인 ${a.distinctDisplayedStoresWithShipping}개 표시 몰 · 재고/판매량 미검증</div>${e.flag.outlier?`<p class="market-warning">가격 주의: 다른 동급 ${e.flag.n} SKU의 중앙값 대비 ${pct(e.flag.premium)}. 이 가격을 비교 앵커에서 제외했습니다.</p>`:''}</div>
 <div class="fair-box"><span class="fair-label">02 / 지표당 가격이 같아지는 참고가</span><strong>${money(e.cap)}</strong><p>각 비교 가격 × 대상 지표 ÷ 비교 지표. 같은 칩 보드는 먼저 중앙값으로 묶고, 칩별 동률 가격의 중앙값을 사용합니다. 단일 최저가가 적정가를 결정하지 않도록 했습니다.</p><div class="fair-formula">비교 ${e.peerN} SKU / ${e.chipN}그룹 · 칩별 25~75분위 ${money(e.capLow)} ~ ${money(e.capHigh)}<br>표본 분산의 요약이며 통계적 신뢰구간이 아닙니다.${e.chipN===1?' 동일칩 한 그룹이라 분위구간이 중앙값과 같습니다.':''}<br>현재가가 참고가의 105% 초과면 ‘비교 제품 우선’. 5%는 정책값입니다.</div><p>견적 변경 시 ${money(e.alternate.current)} / 참고가 ${money(e.alternate.cap)} · ${esc(e.alternate.recommendation)}${e.sensitive?' · 분류가 바뀌어 추천을 보류합니다.':''}${e.quoteGap>=.10?' · 견적 간 '+pct(e.quoteGap)+' 차이로 가격 폭 주의.':''}</p></div>
 <div class="fair-box"><span class="fair-label">03 / 최근 가격 이력 참고</span><strong>${e.reference.n?`${money(e.reference.low)} ~ ${money(e.reference.high)}`:'이력 미수집'}</strong><p>${e.reference.n?`실제 n=${e.reference.n}, PC 주간 라벨의 25분위~중앙값. 배송·카드·집계 기준 미확인. 과거 상품가 중앙값 대비 ${pct(e.historicalPremium)}. 희소 SKU 이력을 적정가로 쓰지 않습니다.`:'새 비교 견적은 현재 스냅샷만 수집했습니다. 과거값·모바일값을 추정하지 않습니다.'}</p></div></div></section></div>
 <section class="panel section-block"><div class="panel-head"><div><div class="eyebrow">MARKET ALTERNATIVES</div><h2>${p.category} 비교군을 한눈에</h2><p class="panel-subtitle">모든 확보 견적을 표시 · 선택 범위에 들지 않거나 근거가 부족한 행은 참고가 산정에서 제외</p></div></div><div class="table-scroll"><table class="data-table alternative-table"><thead><tr><th>제품</th><th>선택 지표</th><th>${statLabel} · ${basisLabel}</th><th>표시 판매처 / 배송 확인 몰</th><th>가격 앵커</th><th>구매 분류</th></tr></thead><tbody>${others.map(({p:x,e:v})=>`<tr class="${x.id===p.id?'selected-row':''}"><td><button class="link-button" data-action="domProduct" data-value="${x.id}">${esc(x.shortName)}</button><br><span class="small-copy">${esc(x.spec)}</span></td><td>${v.metric?`${num(v.metric.value,0)} ${esc(v.metric.unit)}`:'미확보'}</td><td>${money(v.current)}</td><td>${x.quote.displayedSellerCount} / ${x.marketAudit.distinctDisplayedStoresWithShipping}</td><td>${v.anchorAllowed?'가능':'제외'}${e.caps.some(c=>c.id===x.id)?' · 대상 비교에 사용':''}</td><td>${pill(v.recommendation,v.tone)}</td></tr>`).join('')}</tbody></table></div><div class="panel-foot">몰 이름이 달라도 같은 판매자나 기업 계열일 수 있습니다. 21개 견적은 독립 시장 표본 21개를 뜻하지 않습니다. 같은 칩 보드 수를 벤치마크 표본 수에 더하지 않습니다.</div></section>
 ${benchSection(D,all)}
 <section class="panel section-block"><div class="panel-head"><div><h2>국내 가격 이력 · ${esc(p.shortName)}</h2><p class="panel-subtitle">${D.historicalAsOf} 확보 원본 · 현재 견적을 이력에 이어 붙이지 않음</p></div><span class="pill">PC ${pcN} · 모바일 ${mobN}개</span></div>${p.history?`<div class="panel-inner" style="padding-bottom:0"><div class="control-group">${seg('domFrequency',[['weekly','3개월 · 주간 라벨'],['monthly','최대 24개월 · 월간 라벨']],state.domFrequency)}${select('domSurface','출처',[['both','PC + 모바일'],['pc','PC'],['mobile','모바일']],state.domSurface)}</div></div><div id="domestic-history" class="chart-zone"></div><div class="legend"><span><i style="background:#267b61"></i>PC</span><span><i style="background:#9a81bf"></i>모바일</span></div><div class="panel-foot">minPrice 원문. 집계·배송·카드 조건 미확인. 2026년은 스냅샷 문맥 추론이며 일별·주평균·금요일 종가로 재해석하지 않습니다. 2026-10은 미완성 월. 선은 관측 간 안내선입니다.</div>`:'<div class="empty-state">새 비교 견적은 과거 가격·모바일 미수집 · 현재 가격만 표시합니다.</div>'}</section>
 ${conflicts.length?`<details class="audit-details section-block"><summary>월간 PC·모바일 차이 ${conflicts.length}건</summary><div class="table-scroll"><table class="data-table"><thead><tr><th>월</th><th>PC</th><th>모바일</th><th>상태</th></tr></thead><tbody>${conflicts.map(r=>`<tr><td>${r.month_iso}</td><td>${money(r.desktop_price)}</td><td>${money(r.mobile_price)}</td><td>${r.status==='value_mismatch'?'값 불일치 · 양쪽 보존':'모바일만 확보'}</td></tr>`).join('')}</tbody></table></div></details>`:''}
 <section id="domestic-methods" class="panel section-block"><div class="panel-head"><div><div class="eyebrow">EVIDENCE & LIMITATIONS</div><h2>추천의 근거와 빈칸</h2></div>${download('./reports/domestic-value.md','방법 보고서')}</div><div class="panel-inner domestic-methods"><div class="method-grid">
 <div><b>가격 앵커의 조건</b><p>조회 7일 이내·미래 1일 이내, 표시 판매처 10곳 이상, 서로 다른 표시 일반몰 3곳 이상에서 배송 확인, 요약 필드와 첫 견적 일치. 같은 칩(메모리는 같은 세대·용량, SSD는 같은 1TB 클래스)의 타 SKU 3개 이상 대비 3몰 중앙값이 20% 초과하면 가격 주의로 제외합니다. 앵커 품질은 항상 배송 포함 3몰 기준으로 검사합니다. CPU는 같은 모델의 다른 SKU 3개가 없어 이상가 검사가 미적용이며 지표당 가격을 비교합니다. 3·7·10·20%·5%는 화면 정책값입니다.</p></div>
 <div><b>점수와 근거 수준</b><p>같은 지표/가격 최고=100. 시장 전체 순위나 신뢰확률이 아닙니다. CPU는 사용자 제출 집계, GPU는 2025년 리뷰 실측, RAM·SSD는 사양을 사용합니다. 같은 칩의 여러 보드를 성능 표본으로 중복 계산하지 않습니다.</p></div>
 <div><b>선정과 제외</b><p>기존 8개를 보존하고 PALIT 1개에 새 12개를 추가했습니다. 가격 비교 중지 ASUS 4060은 제외했고, 벤치마크만 있는 5070/9070 XT 및 레퍼런스 9060 XT는 대응 국내 견적이 없어 추천에 쓰지 않습니다. 해외직구·리퍼·용량/세대가 다른 RAM/SSD는 섞지 않았습니다.</p></div>
 <div><b>실측의 범위</b><p>PassMark는 PC별 RAM·냉각·전력 설정이 미통제입니다. GPU는 23종 게임 지수이며 최신 드라이버, RT, 생성 프레임, 1% low를 대표하지 않습니다. 카드별 드라이버는 원문에서 서로 다릅니다. 직접 CPU 게임 공통 벤치는 여전히 미확보입니다.</p></div>
 <div><b>모바일과 과거 이력</b><p>기존 8개 상품 셀만 PC·모바일 일치. 모바일 메인 CSR 가격·배송 포함가는 미검증입니다. 주간 96행 일치, 최대 24개월 모바일 185/PC 179행, 값 불일치 5·모바일만 6. 전체 기간 창 감사의 13건 차이와 집계 범위가 다릅니다. 새 비교군의 이력·모바일은 미수집입니다.</p></div>
 <div><b>업그레이드 총비용</b><p>보드·메모리·쿨러·PSU·케이스 교체, 전력·중고 처분가 미반영. CPU 소켓·RAM 세대가 다르면 단품 점수만으로 교체를 결정할 수 없습니다. 표시 몰 수는 독립 업체·재고·판매량이 아닙니다. 미래 가격을 예측하지 않습니다.</p></div></div>
 <div class="quote-breakdown"><h3>선택 견적의 원문과 일반몰</h3><p>요약 상품 ${money(q.productPrice)} + 배송 ${money(q.shipping)} = ${money(q.deliveredPrice)} · 표시 판매처 ${q.displayedSellerCount}곳</p><p>수집 ${esc(q.collectedAt)} · 원문 갱신 시각 미제공 · ${link(q.sourceUrl,'PC')}${q.mobileCheck?' · '+link(q.mobileCheck.sourceUrl,'모바일'):' · 모바일 미수집'}</p><p>SHA-256 <code>${q.sourceSha256}</code></p><details class="audit-details"><summary>확보한 몰별 가격 · 현금/배송 미확인 행 포함 원자료 보기</summary><div class="table-scroll"><table class="data-table"><thead><tr><th>표시 몰</th><th>상품</th><th>배송</th><th>배송 포함</th><th>조건</th></tr></thead><tbody>${a.offers.map(r=>`<tr><td>${esc(r.seller)}</td><td>${money(r.productPrice)}</td><td>${money(r.shipping)}</td><td>${money(r.deliveredPrice)}</td><td>${r.cashOnly?'현금 전용 · 제외':r.shipping===null?'배송 미확인 · 제외':'일반 견적'}</td></tr>`).join('')}</tbody></table></div></details></div>
 <div class="market-peer"><h3>명시적 제외 후보</h3>${D.excluded.map(x=>`<p>${esc(x.name)} — ${esc(x.reason)} ${link(x.sourceUrl,'원문')}</p>`).join('')}</div>
 <details class="audit-details section-block"><summary>성능 출처·발행일 확인</summary><div class="panel-inner source-list">${D.sources.map(s=>`<div class="source-item"><div><strong>${esc(s.name)}</strong><p>${esc(s.scope)}<br>발행 ${s.published??'지속 갱신 또는 날짜 미확인'} · 접근 ${s.accessed}</p></div>${link(s.url,'원문')}</div>`).join('')}</div></details>
 <div class="download-list section-block">${download('./data/domestic.json','국내 전체 JSON')}${download('./data/downloads/domestic_expanded.csv','전체 견적 CSV')}${download('./data/downloads/domestic_benchmarks.csv','실측 근거 CSV')}${download('./data/downloads/domestic_history.csv','기존 이력 CSV')}</div><p class="small-copy section-block">2020–2022년 해외 분석은 <a href="#prices">가격 추이</a>·<a href="#correlations">주가와 상관</a>·<a href="#mining">채굴 붐</a>에서 확인하세요. 국내 현재 견적과 하나의 연속 자료로 합치지 않습니다.</p></div></section>`;
 if(p.history){const series=historySeries(p,state.domFrequency,state.domSurface),dates=series.flatMap(s=>s.points.map(r=>r.date)).sort();lineChart(main.querySelector('#domestic-history'),series,{title:`${p.shortName} 국내 가격 이력`,unit:'KRW · 원문 minPrice',start:dates[0],end:dates.at(-1),monthly:state.domFrequency==='monthly',monthlyLabel:'월간 라벨',showPoints:true,height:310});}
}
